// node --test scripts/publish-map-renderer.test.mjs
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { fileURLToPath } from 'node:url';
import { describe, it } from 'node:test';
import {
  BUNDLE_NAME,
  MODULES,
  PUBLIC_NAMES,
  bundle,
  declaredNames,
  hashFileText,
  stripModule,
} from './publish-map-renderer.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const DIST = path.join(here, '..', 'services', 'shattered-maps-core', 'dist');

const fake = () => ({
  'schema.js':
    "export const DIRECTIONS = ['N', 'S'];\nexport function a() { return 1; }\n//# sourceMappingURL=schema.js.map\n",
  'hierarchy.js':
    "import { DIRECTIONS } from './schema.js';\nexport function sliceMap() { return DIRECTIONS.length; }\n",
  'terrainPalette.js': "export const TERRAIN = [{ sector: 'city' }];\n",
  'render.js':
    "export const MAX_RENDER_ROOMS = 5;\nexport function escapeXml(s) { return s; }\nexport function renderSvg() { return '<svg/>'; }\n",
});

describe('stripModule', () => {
  it('removes relative imports, export keywords and the source-map comment, and reports the imports', () => {
    const r = stripModule(
      'x.js',
      "import { A, B } from './schema.js';\nimport {\n  C,\n} from './other.js';\nexport function f() {}\nexport const k = 1;\n//# sourceMappingURL=x.js.map\n",
    );
    assert.deepEqual(r.imports, ['schema.js', 'other.js']);
    assert.equal(r.code, 'function f() {}\nconst k = 1;');
  });
  it('treats CRLF like LF', () => {
    assert.equal(
      stripModule('x.js', 'export const k = 1;\r\nexport const j = 2;\r\n').code,
      'const k = 1;\nconst j = 2;',
    );
  });
  it('refuses a package import and an export list it does not understand', () => {
    assert.throws(() => stripModule('x.js', "import fs from 'node:fs';\n"), /import this script does not understand/);
    assert.throws(
      () => stripModule('x.js', 'const a = 1;\nexport { a };\n'),
      /export form this script does not understand/,
    );
  });
});

describe('declaredNames', () => {
  it('lists top-level functions, consts, lets and classes only', () => {
    const names = declaredNames(
      'function a() {\n  const inner = 1;\n}\nconst b = 2;\nlet c;\nclass D {}\nasync function e() {}\n  const indented = 3;',
    );
    assert.deepEqual(names, ['a', 'b', 'c', 'D', 'e']);
  });
});

describe('bundle', () => {
  it('joins the modules in order inside one strict IIFE that exposes only the public names', () => {
    const text = bundle(fake());
    assert.match(text, /^\/\/ GENERATED by/);
    assert.ok(text.indexOf('// ---- schema.js') < text.indexOf('// ---- hierarchy.js'));
    assert.ok(text.indexOf('// ---- hierarchy.js') < text.indexOf('// ---- render.js'));
    assert.ok(!/^\s*(import|export)\s/m.test(text));
    const sandbox = { globalThis: undefined };
    sandbox.globalThis = sandbox;
    vm.runInNewContext(text, sandbox);
    assert.deepEqual(Object.keys(sandbox.ShatteredMapsCore).sort(), [...PUBLIC_NAMES].sort());
    assert.equal(sandbox.ShatteredMapsCore.sliceMap(), 2);
    assert.equal(sandbox.ShatteredMapsCore.renderSvg(), '<svg/>');
    assert.ok(Object.isFrozen(sandbox.ShatteredMapsCore));
  });
  it('is the same bytes every time', () => {
    assert.equal(bundle(fake()), bundle(fake()));
  });
  it('refuses a missing module, an unknown import, an import from later in the order and a duplicate name', () => {
    const missing = fake();
    delete missing['render.js'];
    assert.throws(() => bundle(missing), /render.js is missing/);
    const unknown = fake();
    unknown['render.js'] = "import { z } from './zzz.js';\n" + unknown['render.js'];
    assert.throws(() => bundle(unknown), /not part of the bundle recipe/);
    const later = fake();
    later['schema.js'] = "import { renderSvg } from './render.js';\n" + later['schema.js'];
    assert.throws(() => bundle(later), /would come after it/);
    const dup = fake();
    dup['render.js'] += 'function a() {}\n';
    assert.throws(() => bundle(dup), /declares a, which schema.js declares too/);
  });
  it('refuses a build that no longer declares a public name', () => {
    const gone = fake();
    gone['render.js'] = gone['render.js'].replace("export function renderSvg() { return '<svg/>'; }\n", '');
    assert.throws(() => bundle(gone), /does not declare renderSvg/);
  });
});

describe('hashFileText', () => {
  it('is sha256 of the text, a space pair, and the bundle name', () => {
    assert.match(
      hashFileText('abc'),
      new RegExp(`^ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad  ${BUNDLE_NAME}\\n$`),
    );
  });
});

describe(
  'the real build',
  { skip: !MODULES.every((m) => fs.existsSync(path.join(DIST, m))) && 'shattered-maps-core is not built' },
  () => {
    const files = Object.fromEntries(MODULES.map((m) => [m, fs.readFileSync(path.join(DIST, m), 'utf8')]));
    it('is deterministic and renders a one-room area to a self-contained SVG', () => {
      const text = bundle(files);
      assert.equal(text, bundle(files));
      const sandbox = {};
      sandbox.globalThis = sandbox;
      vm.runInNewContext(text, sandbox);
      const core = sandbox.ShatteredMapsCore;
      const map = {
        version: 1,
        continents: [
          {
            id: 'c',
            name: 'C',
            areas: [
              {
                id: 'a',
                name: 'A',
                placement: null,
                subzones: [
                  {
                    id: 's',
                    name: 'S',
                    kind: 'consistent',
                    rooms: [{ id: 'r1', title: 'Hall <&>', exits: {}, sources: [], coords: { x: 0, y: 0, z: 0 } }],
                  },
                ],
              },
            ],
          },
        ],
        links: [],
      };
      const slice = core.sliceMap(map, 'area', 'a');
      const svg = core.renderSvg(slice, { layout: 'grid' });
      assert.match(svg, /^<svg/);
      assert.ok(!svg.includes('<script'));
      assert.ok(svg.includes('Hall &lt;&amp;&gt;'));
    });
  },
);
